with RecentSubscriptions as (select * from subscriptions where end_date > '2023-12-01' and plan = 'enterprise' and customer_id = 5), subscriptions_stats as (select plan, case when monthly_fee >= 230 then 'high' when monthly_fee >= 63 then 'mid' else 'low' end as monthly_fee_bucket, min(monthly_fee) as min_monthly_fee, max(monthly_fee) as max_monthly_fee from RecentSubscriptions group by plan, case when monthly_fee >= 230 then 'high' when monthly_fee >= 63 then 'mid' else 'low' end) select * from subscriptions_stats where max_monthly_fee < 180;
